(function(){
 'use strict';
 const $=id=>document.getElementById(id),key='kanji_beginner_v1';
 let previousSave=false,progress={},query='',enteredBattle=false,lettersView='team',recordsView='rank';
 try{previousSave=!!localStorage.getItem('moji_otoshi_save_v5');progress=JSON.parse(localStorage.getItem(key)||'{}')||{};}catch{}
 const newcomer=!previousSave||!!progress.newcomer;
 function saveProgress(){try{localStorage.setItem(key,JSON.stringify(progress));}catch{}}
 window.markTutorialSeen=completed=>{if(!previousSave)progress.newcomer=true;progress.seen=true;if(completed)progress.completed=true;saveProgress();renderPlayHub();};
 window.shouldOfferTutorial=()=>{let pending=false;try{pending=!!sessionStorage.getItem('kanji_friend_room')||sessionStorage.getItem('kanji_online_search')==='1';}catch{}return !previousSave&&!progress.seen&&!pending;};
 window.dismissBeginnerGuide=()=>{progress.guideDismissed=true;saveProgress();renderPlayHub();};
 const node=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text)n.textContent=text;return n;};
 function renderSpecialTrialCatalogue(){const box=$('special-trial-catalogue');if(!box)return;box.replaceChildren();const pool=new Set(KanjiSpecialChallenge.squadsFor(KANJI_DATABASE).flatMap(s=>s.chars)),traits=KanjiTraits.catalogue.filter(t=>pool.has(t.char));$('special-trial-catalogue-count').textContent=`対象は${traits.length}種類。追加された特殊文字も、試練・特性の練習・全効果一覧に反映します。`;for(const t of traits){const row=node('p','inventory-note'),title=node('strong','',t.char+'：'+t.name+'　');row.append(title,document.createTextNode(KanjiAbilityGuide.text(t,'trait')));box.append(row);}}
 function details(title,...children){const d=node('details','mode-details'),s=node('summary','',title);d.append(s,...children.filter(Boolean));return d;}
 function tabs(host,prefix,labels,select){
  const bar=node('div','screen-subtabs');bar.setAttribute('role','tablist');bar.setAttribute('aria-label',prefix==='letters'?'文字の項目':'記録の項目');const panes={};
  for(const [id,label]of labels){const b=node('button','',label);b.type='button';b.id=prefix+'-tab-'+id;b.setAttribute('role','tab');b.setAttribute('aria-controls',prefix+'-panel-'+id);b.onclick=()=>select(id);bar.append(b);const p=node('section','screen-subpanel');p.id=prefix+'-panel-'+id;p.setAttribute('role','tabpanel');p.setAttribute('aria-labelledby',b.id);host.append(p);panes[id]=p;}
  bar.addEventListener('keydown',e=>{const a=[...bar.children],i=a.indexOf(document.activeElement);if(i<0)return;let next;if(e.key==='ArrowRight')next=(i+1)%a.length;else if(e.key==='ArrowLeft')next=(i+a.length-1)%a.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=a.length-1;else return;e.preventDefault();a[next].click();a[next].focus();});
  host.insertBefore(bar,host.querySelector('.screen-subpanel'));return panes;
 }
 function selectPane(prefix,id){document.querySelectorAll('#'+prefix+'-panel-'+id+', [id^="'+prefix+'-panel-"]').forEach(p=>{p.hidden=p.id!==prefix+'-panel-'+id;});document.querySelectorAll('[id^="'+prefix+'-tab-"]').forEach(b=>{const active=b.id===prefix+'-tab-'+id;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});}
 function refreshOwnedFilter(){const f=gameState.currentFilter||'all';const summary=$('owned-filters')?.querySelector('summary');if(summary)summary.textContent='絞り込み：'+(f==='all'?'すべて':f==='fish'?'魚偏の文字':f==='element'?'元素文字':f==='special'?'特殊文字':f==='secret'?'？':`JIS第${f}水準`);}
 const originalFilter=window.filterCollection;window.filterCollection=filter=>{originalFilter(filter);if($('owned-filters'))refreshOwnedFilter();};
 window.setLettersView=id=>{if(!['team','owned','book'].includes(id))return;lettersView=id;selectPane('letters',id);if(id==='owned')renderCollection();};
 window.setRecordsView=id=>{if(!['rank','missions','ranking','replay'].includes(id))return;recordsView=id;selectPane('records',id);if(id==='ranking')loadLeaderboard();};
 const normalize=s=>String(s||'').normalize('NFKC').toLowerCase().replace(/[ァ-ヶ]/g,c=>String.fromCharCode(c.charCodeAt(0)-96));
 const searchCache=new Map();window.ownedCharacterMatches=item=>{if(!query)return true;const source=window.KANJI_READINGS?.[item.char],key=(source||[]).join('\0'),old=searchCache.get(item.char);let values;if(old&&old.source===source&&old.key===key)values=old.values;else{values=[normalize(item.char),...getRealReadings(item.char).map(normalize)];searchCache.set(item.char,{source,key,values});}return values.some(v=>v.includes(query));};
 function modeCard(id,copy){const card=$(id).closest('.glass-panel'),notes=[...card.querySelectorAll(':scope > .inventory-note')],rankButton=card.querySelector('button:not([id])');card.classList.add('mode-card');card.insertBefore(node('p','mode-summary',copy),card.querySelector('h3').nextSibling);card.append(details(id==='btn-start-special'?'ルール':'ルール・ランキング',...notes,rankButton));return card;}
 function modeRewards(card,coins,exp,points,cpu=false){const box=node('dl','mode-rewards');box.setAttribute('aria-label','報酬とポイント');for(const [label,value,key]of [['文',coins,'coins'],['経験値',exp,'exp'],['ポイント',points,'points']]){const row=node('div','mode-reward-row'),term=node('dt','',label),description=node('dd','',value);if(cpu)description.id='cpu-mode-reward-'+key;row.append(term,description);box.append(row);}const summary=card.querySelector('.mode-summary');summary.after(box);}
 function organize(){
  const hub=$('play-hub'),cpu=document.querySelector('.match-cpu-group'),cpuPanel=cpu.querySelector('.glass-panel'),cpuStart=cpu.querySelector(':scope > button');cpu.classList.add('mode-card','glass-panel');cpuStart.id='btn-start-cpu';cpuStart.textContent='CPU戦の相手を確認';cpuStart.className='inventory-action';cpuPanel.querySelector('h3').textContent='難易度';cpu.insertBefore(node('p','mode-summary','まずは通常対戦。勝利で文と段位ポイントを獲得。'),cpuPanel);cpuPanel.append(details('難易度と報酬の説明',$('diff-description')));renderSpecialTrialCatalogue();hub.append(cpu,modeCard('btn-start-endless','勝つほど相手が強くなる連戦。文と育成経験値を獲得。'),modeCard('btn-start-special','能力別の5テーマを攻略して総合試練へ。勝利で240文・経験値なし。'));
  const skill=node('section','glass-panel mode-card');skill.id='play-cpu-skill';const skillButton=node('button','inventory-action','CPU腕試しに挑戦');skillButton.id='btn-play-cpu-skill';skillButton.type='button';skillButton.onclick=()=>openCpuSkillChallenges();skill.append(node('h3','','CPU腕試し'),node('p','mode-summary','毎月変わる貸出文字で挑戦。育成に左右されない得点ランキング。'),skillButton);hub.insertBefore(skill,cpu.nextSibling);
  const practice=document.querySelector('.practice-menu');practice.classList.add('mode-card');practice.querySelector('p').className='mode-summary';practice.querySelector('p').textContent='条件に合わせる・1回の発射で勝つ腕試し。初回達成で文を獲得。';hub.append(practice);
  modeRewards(cpu,'勝利50文／敗北20文／引き分け30文','撃破した自分の文字が獲得','段位：勝利＋25／敗北−15／引き分け±0',true);
  selectCpuDifficulty(currentCpuDifficulty);
  modeRewards($('btn-start-endless').closest('.mode-card'),'勝利50〜200文（進行に応じて増加）／敗北・引き分け0文','撃破した自分の文字が獲得','段位ポイントは変動なし');
  modeRewards($('btn-start-special').closest('.mode-card'),'勝利240文／敗北20文／引き分け30文','獲得なし','段位ポイントは変動なし');
  modeRewards(skill,'獲得なし','獲得なし','自己ベストと得点ランキングを更新');
  modeRewards(practice,'初回達成時のみ獲得（課題ごとに表示）','獲得なし','段位ポイントは変動なし');
  for(const [card,copy]of [[cpu,'育成したい・操作に慣れたい'],[skill,'同じ条件で得点を競いたい'],[$('btn-start-endless').closest('.mode-card'),'育てた編成で連勝に挑みたい'],[$('btn-start-special').closest('.mode-card'),'特殊能力を攻略したい'],[practice,'条件に合わせて編成を考えたい']]){const purpose=node('p','mode-purpose',copy);card.querySelector('h3').after(purpose);}
  const matches=$('screen-matches').firstElementChild;matches.querySelector('h2').textContent='対戦';matches.querySelector('.match-rp-card .inventory-note').textContent='対人RPの近い相手とマッチ。CPUの段位・段位ポイントは問いません。';
  const deck=$('screen-deck').firstElementChild,team=deck.querySelector('.deck-team-panel'),owned=deck.querySelector('.owned-characters-panel'),book=deck.querySelector('.character-collection-panel'),usage=$('btn-usage-records').parentElement,goals=$('btn-collection-goals'),goalSummary=$('collection-goal-summary'),links=$('btn-team-links'),traits=$('btn-traits');deck.querySelector('h2').textContent='文字';deck.querySelector('h2').nextElementSibling.textContent='編成・所持文字・図鑑を切り替えられます。';
  const goalMenu=node('div','adventure-menu');goalMenu.append(goals,goalSummary);links.parentElement.remove();
  const panes=tabs(deck,'letters',[['team','編成'],['owned','所持'],['book','図鑑']],setLettersView);panes.team.append(team);const choose=node('button','inventory-action secondary','所持文字から選ぶ');choose.id='btn-choose-owned';choose.onclick=()=>setLettersView('owned');team.querySelector('.deck-actions').append(choose);team.querySelector('.deck-action-help').textContent='カードをタップでルビ・能力を確認。左右にスライドで順番を入れ替え。';team.append(details('文字の連携',links));panes.owned.append(owned);panes.book.append(book,traits);traits.classList.add('inventory-action','secondary');
  $('deck-slots-container').addEventListener('click',e=>{const slot=e.target.closest('[data-deck-slot]');if(slot&&!gameState.deck[Number(slot.dataset.deckSlot)])beginOwnedDeckChoice(Number(slot.dataset.deckSlot));});
  $('deck-slots-container').addEventListener('keydown',e=>{const slot=e.target.closest('[data-deck-slot]');if(['Enter',' '].includes(e.key)&&slot&&!gameState.deck[Number(slot.dataset.deckSlot)]){e.preventDefault();beginOwnedDeckChoice(Number(slot.dataset.deckSlot));}});
  const search=node('div','owned-search'),label=node('label','','漢字・読みを検索'),input=document.createElement('input');label.htmlFor='owned-character-search';input.id=label.htmlFor;input.type='search';input.placeholder='例：山・やま';input.autocomplete='off';input.addEventListener('input',()=>{query=normalize(input.value.trim());renderCollection();});search.append(label,input);owned.insertBefore(search,owned.children[1]);const filters=$('filter-all').parentElement;owned.insertBefore(details('絞り込み',$('filter-all').parentElement),search.nextSibling);filters.parentElement.id='owned-filters';const sort=$('collection-sort').parentElement,bulk=owned.querySelector('.bulk-ruby-panel'),bulkNote=bulk.nextElementSibling;sort.classList.add('owned-sort-row');owned.insertBefore(details('並び替え・一括操作・保護設定',sort,bulk,bulkNote,$('auto-lock-panel')),$('collection-grid'));owned.lastElementChild.classList.add('owned-grid');
  const rank=$('screen-rank').firstElementChild;rank.classList.remove('my-auto');const profile=rank.querySelector('.profile-card');profile.hidden=true;const heading=rank.querySelector('.text-center');heading.classList.remove('text-center');heading.querySelector('h2').textContent='記録';heading.querySelector('p').textContent='段位・ミッション・ランキング・リプレイ';const rankCard=$('rank-hub-icon').parentElement,trials=$('rank-trials').parentElement,ranking=$('leaderboard-rule').parentElement,list=[...rank.children].find(n=>n.querySelector('h3')?.textContent==='段位一覧'),help=$('app-help'),replays=document.querySelector('.replay-menu');const rpanes=tabs(rank,'records',[['rank','段位'],['missions','ミッション'],['ranking','ランキング'],['replay','リプレイ']],setRecordsView);rpanes.rank.append(rankCard,trials,details('段位一覧',list));rpanes.missions.append(goalMenu,usage);rpanes.ranking.append(ranking);rpanes.replay.append(replays);rank.append(help,$('recovery-code-panel'),$('guest-player-panel'),$('sharing-policy'));const replayTutorial=node('button','inventory-action secondary','操作を練習する');replayTutorial.onclick=()=>openGameTutorial();help.insertBefore(replayTutorial,help.children[1]);filterCollection(gameState.currentFilter||'all');setLettersView(lettersView);setRecordsView(recordsView);
 }
 window.renderPlayHub=()=>{
  const resume=enteredBattle&&battleMode!=='friend'||friendRoom&&['preparing','playing','finished'].includes(friendRoom.status);$('btn-return-battle').hidden=!resume;$('btn-return-battle').textContent=soloBattlePending?'準備中の対局に戻る':isBattleEnded?'対局の結果に戻る':'進行中の対局に戻る';
  const card=$('beginner-next');card.hidden=!newcomer||!!progress.guideDismissed;if(card.hidden)return;let title,note,label;
  if(!progress.cpuWins){title='まずはCPU戦で遊ぼう';note='相手を確認し、スタートを押して対局。最初の3文字で遊べます。';label='通常CPU戦を準備';}
  else if(gameState.inventory.length<=3){title='報酬の文で文字を召喚';note='新しい文字を集めて、編成の選択肢を増やそう。';label='召喚へ';}
  else{title='新しい文字で編成';note='おすすめ編成で3文字を選び、文字の詳細からルビを試そう。';label='編成を見る';}
  $('beginner-next-title').textContent=title;$('beginner-next-note').textContent=note;$('btn-beginner-next').textContent=label;
 };
 window.takeBeginnerNextStep=()=>{if(!progress.cpuWins){selectCpuDifficulty('normal');startMatchmaking();}else if(gameState.inventory.length<=3)switchTab('gacha');else{switchTab('deck');setLettersView('team');}};
 const originalSwitch=window.switchTab;window.switchTab=tab=>{if(tab==='battle')enteredBattle=true;originalSwitch(tab);if(tab==='play')renderPlayHub();if(tab==='deck'&&preparationEditing)setLettersView('team');};
 const originalRanking=window.showRanking;window.showRanking=mode=>{setRecordsView('ranking');originalRanking(mode);};
 const originalFinish=window.finishBattleResult;window.finishBattleResult=(winner,verdict)=>{const win=!soloBattlePending&&!isBattleEnded&&battleMode==='classic'&&winner===true;originalFinish(winner,verdict);if(win&&isBattleEnded){progress.cpuWins=(progress.cpuWins||0)+1;saveProgress();}};
 window.addEventListener('load',()=>{organize();const params=new URLSearchParams(location.search),linked=params.get('online')==='1'||params.has('room')||params.has('friend');if(!friendRoom&&!linked)switchTab('play');else renderPlayHub();});
})();
